const $=s=>document.querySelector(s), ns='http://www.w3.org/2000/svg';
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e}
let seed=36;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};
const branches=$('#branches'), foliage=$('#foliage');
svg('path',{d:'M 634 850 Q 691 814 675 696 Q 665 603 700 507 Q 716 590 729 685 Q 719 790 774 850 Z',fill:'url(#bark)',stroke:'none'},branches);
function branch(x,y,angle,length,width,level){const x2=x+Math.cos(angle)*length,y2=y+Math.sin(angle)*length;svg('path',{d:`M${x} ${y} Q${x+(x2-x)*.3+12} ${y+(y2-y)*.65} ${x2} ${y2}`,'stroke-width':width},branches);if(level){branch(x2,y2,angle-.35-rand()*.35,length*.73,width*.64,level-1);branch(x2,y2,angle+.35+rand()*.4,length*.72,width*.62,level-1)}else{for(let i=0;i<9;i++){let cx=x2+(rand()-.5)*110,cy=y2+(rand()-.5)*70;svg('ellipse',{cx,cy,rx:20+rand()*33,ry:13+rand()*23,fill:'url(#leaf)',opacity:.65+rand()*.35},foliage);for(let j=0;j<12;j++)svg('ellipse',{cx:cx+(rand()-.5)*70,cy:cy+(rand()-.5)*50,rx:2+rand()*5,ry:2+rand()*3,fill:rand()>.5?'var(--leaf-light)':'var(--leaf-dark)',opacity:.7},foliage);if(rand()>.5){let d=`M${cx} ${cy} Q${cx+30} ${cy+100} ${cx+10} ${cy+160}`;svg('path',{d,fill:'none',stroke:'var(--leaf-dark)','stroke-width':4,opacity:.7},foliage);for(let k=0;k<25;k++)svg('ellipse',{cx:cx+Math.sin(k/9)*15+(rand()-.5)*15,cy:cy+k*6,rx:4+rand()*5,ry:3+rand()*4,fill:'var(--leaf-light)',opacity:.85},foliage)}}}}
branch(697,658,-2.1,170,51,4);branch(703,610,-1.3,150,40,4);branch(704,684,-.88,210,48,4);branch(687,708,-2.8,183,34,3);
for(let i=0;i<18;i++)svg('path',{d:`M${650+i*6} 842 Q${673+i*2} 755 ${686+i*2} ${595+rand()*100}`,'stroke-width':1+rand()*2},$('#barklines'));
for(let i=0;i<95;i++){let f=document.createElement('b');f.textContent=i%4?'✿':'·';f.style.cssText=`left:${rand()*100}%;top:${rand()*65}%;transform:scale(${.5+rand()})`;$('#flowers').append(f)}
for(let i=0;i<29;i++){let e=document.createElement('i');e.className='particle';e.style.cssText=`left:${rand()*100}%;top:${20+rand()*30}%;animation-delay:-${rand()*18}s;animation-duration:${14+rand()*12}s`;$('#particles').append(e)}
// Each portfolio root is configured here; add a title, description and URL when ready.
const projects=[{title:'Project A',description:'Something new is taking root',url:null,x:18,y:570,cx:270},{title:'Project B',description:'An idea, a little deeper',url:null,x:40,y:920,cx:560},{title:'Project C',description:'Room for something wonderful',url:null,x:63,y:1050,cx:840},{title:'Project D',description:'A new direction to explore',url:null,x:84,y:690,cx:1120}];
projects.forEach((p,i)=>{let x=p.x*14,y=p.y;let d=`M700 0 C${700+(x-700)*.15} 190 ${p.cx} ${y*.5} ${x} ${y}`;svg('path',{d,fill:'none',stroke:'url(#root-color)','stroke-width':24-i*3,'stroke-linecap':'round'},$('#main-roots'));let line=svg('path',{d,fill:'none',stroke:'#d7ad70','stroke-width':2,opacity:.5},$('#main-roots'));for(let k=0;k<22;k++){let t=.16+k/29;let bx=700+(x-700)*t,by=y*t;let dir=k%2?1:-1;let ex=bx+dir*(40+rand()*160);let ey=by+90+rand()*150;svg('path',{d:`M${bx} ${by} Q${ex} ${by+40} ${ex} ${ey} m${(bx-ex)*.4} ${-50} q${dir*40} 25 ${dir*75} 80`,fill:'none',stroke:'#a17a50','stroke-width':1+rand()*3,opacity:.4},$('#fine-roots'))}let node=document.createElement(p.url?'a':'button');node.className='node';node.style.left=p.x+'%';node.style.top=y/14+'%';node.innerHTML=`<span class="orb"></span><span class="number">ROOT 0${i+1}</span><strong>${p.title}</strong><small>Still growing</small><span class="hint">Discover this root ↗</span>`;if(p.url){node.href=p.url;node.target='_blank';node.rel='noopener noreferrer'}else node.onclick=()=>{$('#dialog-title').textContent=p.title;$('#project-dialog').showModal()};node.onmouseenter=()=>line.setAttribute('opacity',1);node.onmouseleave=()=>line.setAttribute('opacity',.5);$('#project-nodes').append(node)});
const captions={spring:'a season for beginnings',summer:'a season to flourish',fall:'a season for becoming',winter:'a season to dream'};
function choose(s){document.body.dataset.season=s;document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.season===s));$('#season-caption').textContent=s[0].toUpperCase()+s.slice(1)+' · '+captions[s];try{localStorage.setItem('living-tree-season',s)}catch{}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>choose(b.dataset.season));let saved='spring';try{saved=localStorage.getItem('living-tree-season')||saved}catch{}choose(captions[saved]?saved:'spring');
function explore(){$('#roots').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}$('#explore').onclick=explore;$('#scroll').onclick=explore;$('#close').onclick=$('#return').onclick=()=>$('#project-dialog').close();$('#project-dialog').addEventListener('click',e=>{if(e.target===$('#project-dialog'))$('#project-dialog').close()});
